<script setup lang="ts">
import {ref,computed,watch,onUnmounted} from 'vue'
import Sheet from '../components/Sheet.vue'
import {useLocal} from '../stores/local'
import {unicodeOffset,type Document} from '../domain/local-contract'
import type {LocalBranch} from './contract'
import {compareReadingLines} from './line-comparison-runtime'
const props=defineProps<{storyId:string;branches:Document<LocalBranch>[];selected:string}>(),emit=defineEmits<{close:[]}>(),store=useLocal()
const left=ref(props.selected),right=ref(props.selected?'':props.branches[0]?.id||''),result=ref<Awaited<ReturnType<typeof compareReadingLines>>|null>(null),error=ref(''),busy=ref(false),tab=ref<'text'|'facts'|'events'|'timeline'>('text'),showSame=ref(false),factPage=ref(0),previous=ref<{left:number;right:number}[]>([])
const visibleRows=computed(()=>result.value?.rows.filter(row=>showSame.value||row.kind!=='same')||[])
let control=new AbortController(),epoch=0,disposed=false
function link(branchId:string|null,id:string,offset:number){return {path:'/local/read/'+props.storyId,query:{branch:branchId||undefined,paragraph:id,offset:String(offset)}}}
const eventKinds:Record<string,string>={character:'人物',item:'物品',location:'地点',time:'时间',motivation:'动机',knowledge:'认知',relationship:'关系',unresolved:'线索',event:'事件'}
function excerpt(text:string){const end=unicodeOffset(text,1800);return text.slice(0,end)+(end<text.length?'…':'')}
async function load(lo=0,ro=0){control.abort();control=new AbortController();const signal=control.signal,token=++epoch,vault=store.vault;if(!vault)return;error.value='';busy.value=true;try{const value=await compareReadingLines(vault,props.storyId,left.value||null,right.value||null,signal,lo,ro);if(!disposed&&token===epoch&&store.vault===vault&&vault.unlocked)result.value=value}catch(e){if(!disposed&&token===epoch&&!signal.aborted){result.value=null;error.value=(e as Error).message}}finally{if(!disposed&&token===epoch)busy.value=false}}
function next(){const page=result.value?.page;if(!page)return;previous.value.push({left:page.leftOffset,right:page.rightOffset});void load(page.nextLeft,page.nextRight)}
function back(){const page=previous.value.pop();if(page)void load(page.left,page.right)}
watch([left,right],()=>{previous.value=[];factPage.value=0;result.value=null;void load()},{immediate:true})
watch(()=>store.vault,()=>{epoch++;control.abort();result.value=null;error.value='';busy.value=false})
onUnmounted(()=>{disposed=true;epoch++;control.abort();result.value=null})
</script>
<template><Sheet title="比较故事线" @close="emit('close')"><div class="line-comparison"><div class="comparison-selects"><label>左侧<select v-model="left" aria-label="比较左侧故事线"><option value="">原文</option><option v-for="b in branches" :key="b.id" :value="b.id">{{b.value.name}}</option></select></label><label>右侧<select v-model="right" aria-label="比较右侧故事线"><option value="">原文</option><option v-for="b in branches" :key="b.id" :value="b.id">{{b.value.name}}</option></select></label></div><div class="comparison-tabs"><button :aria-pressed="tab==='text'" @click="tab='text'">正文</button><button :aria-pressed="tab==='facts'" @click="tab='facts';factPage=0">人物设定</button><button :aria-pressed="tab==='events'" @click="tab='events';factPage=0">事件差异</button><button :aria-pressed="tab==='timeline'" @click="tab='timeline';factPage=0">时间线</button><span>已读范围</span></div><p v-if="error" class="final-error" role="alert">{{error}}<button @click="load()">重新比较</button></p><p v-else-if="busy" role="status">正在比较…</p><template v-else-if="result"><div class="comparison-common"><span>共同前文 · {{result.common.paragraphCount}} 段</span><RouterLink v-if="result.common.last" :to="link(result.left.branchId,result.common.last.leftId,result.common.last.offset)" @click="emit('close')">阅读分叉处</RouterLink></div><template v-if="tab==='text'"><label class="final-check"><input v-model="showSame" type="checkbox">显示相同片段</label><p v-if="!visibleRows.length" class="final-subtle" role="status">{{result.rows.length?'本页只有相同片段，开启显示相同片段可查看。':'已读范围内没有不同正文。'}}</p><article v-for="(row,n) in visibleRows" :key="n" class="comparison-row" :class="'comparison-'+row.kind"><small>{{row.kind==='same'?'相同片段':row.kind==='different'?'两线不同':row.kind==='left'?result.left.name+'独有':result.right.name+'独有'}}</small><div class="comparison-columns"><section v-for="side in (['left','right'] as const)" :key="side"><h3>{{result[side].name}}</h3><template v-if="row[side]"><p>{{excerpt(row[side]!.text)}}</p><RouterLink :to="link(result[side].branchId,row[side]!.id,row[side]!.start)" @click="emit('close')">{{row[side]!.text.length>1800?'阅读完整段落':'定位原句'}}</RouterLink></template><span v-else class="final-subtle">此处没有已读正文</span></section></div></article><div class="final-page-actions"><button :disabled="!previous.length" @click="back">上一页</button><span>{{previous.length+1}}</span><button :disabled="!result.page.hasMore" @click="next">下一页</button></div></template><template v-else-if="tab==='facts'"><p v-if="!result.facts.left.length&&!result.facts.right.length" class="final-subtle">暂无设定差异。</p><div v-else class="comparison-columns comparison-facts"><section v-for="side in (['left','right'] as const)" :key="side"><h3>{{result[side].name}}</h3><article v-for="(fact,n) in result.facts[side].slice(factPage*20,factPage*20+20)" :key="n"><strong>{{fact.name}}</strong><small>{{fact.confidence==='explicit'?'明确':'推测'}}</small><p>{{fact.text}}</p><RouterLink v-for="e in fact.evidence" :key="e.id+':'+e.offset" :to="link(result[side].branchId,e.id,e.offset)" @click="emit('close')">{{e.quote}}</RouterLink></article></section></div><div v-if="result.facts.left.length||result.facts.right.length" class="final-page-actions"><button :disabled="factPage===0" @click="factPage--">上一页</button><span>{{factPage+1}}</span><button :disabled="(factPage+1)*20>=Math.max(result.facts.left.length,result.facts.right.length)" @click="factPage++">下一页</button></div></template><template v-else><p v-if="result.sourceWarnings.left.length||result.sourceWarnings.right.length" class="final-subtle">部分已读正文未附事件记录。</p><p v-if="!result[tab].left.length&&!result[tab].right.length" class="final-subtle">{{tab==='events'?'暂无已读事件差异。':'暂无已读事件记录。'}}</p><div v-else class="comparison-columns comparison-facts"><section v-for="side in (['left','right'] as const)" :key="side"><h3>{{result[side].name}}</h3><article v-for="event in result[tab][side].slice(factPage*20,factPage*20+20)" :key="event.proof"><strong>{{eventKinds[event.kind]||'事件'}}</strong><small>{{event.frame==='past'?'回忆':'当前'}} · {{event.certainty==='inferred'?'推测':'叙述'}}</small><p>{{excerpt(event.text)}}</p><RouterLink v-for="e in event.evidence" :key="e.id+':'+e.offset" :to="link(result[side].branchId,e.id,e.offset)" @click="emit('close')">定位原句</RouterLink></article></section></div><div v-if="result[tab].left.length||result[tab].right.length" class="final-page-actions"><button :disabled="factPage===0" @click="factPage--">上一页</button><span>{{factPage+1}}</span><button :disabled="(factPage+1)*20>=Math.max(result[tab].left.length,result[tab].right.length)" @click="factPage++">下一页</button></div></template></template></div></Sheet></template>
<style scoped>.line-comparison{display:grid;gap:20px}.comparison-selects,.comparison-columns{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.comparison-selects label{display:grid;gap:8px}.comparison-selects select{min-width:0;width:100%}.comparison-tabs,.comparison-common{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.comparison-tabs button[aria-pressed=true]{background:var(--wash);color:var(--accent);border-color:var(--accent)}.comparison-tabs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.comparison-tabs button{justify-content:center}.comparison-tabs span{grid-column:1/-1;justify-self:end;color:var(--quiet);font-size:12px}.comparison-common{font-size:13px;justify-content:space-between;color:var(--quiet)}.comparison-common a,.comparison-columns a{color:var(--accent);font-size:12px;overflow-wrap:anywhere}.comparison-row{border:1px solid var(--edge);border-radius:14px;padding:18px;min-width:0}.comparison-row>small{display:block;color:var(--quiet);margin-bottom:12px}.comparison-columns section{min-width:0}.comparison-columns h3{margin:0 0 10px;font:18px var(--font-serif,serif);overflow-wrap:anywhere}.comparison-columns p{white-space:pre-wrap;overflow-wrap:anywhere;font:16px/1.9 var(--font-serif,serif)}.comparison-facts article{border-top:1px solid var(--edge);padding:16px 0}.comparison-facts small{margin-left:10px;color:var(--quiet);font-size:11px}.comparison-facts a{display:block;margin-top:8px}@media(max-width:600px){.comparison-tabs{grid-template-columns:repeat(2,minmax(0,1fr))}.comparison-columns{grid-template-columns:1fr}.comparison-row{padding:14px}.comparison-columns section+section{border-top:1px dashed var(--edge);padding-top:16px}}</style>
